"""Tanki Ratings API client with proxy pool integration."""from __future__ import annotationsimport asyncioimport loggingimport osfrom typing import TYPE_CHECKING, Any, Dict, Optional, Tupleimport aiohttpif TYPE_CHECKING:    from proxy.pool import ProxyPoollogger = logging.getLogger(__name__)class TankiStatsError(Exception):    """Base exception for Tanki stats client errors."""class RateLimitExceeded(TankiStatsError):    """Raised when Tanki API responds with HTTP 429."""class ProxyConnectionError(TankiStatsError):    """Transient network/proxy failure; safe to retry with another proxy."""    def __init__(self, message: str, *, log_reason: Optional[str] = None) -> None:        super().__init__(message)        self.log_reason = log_reason or messagedef profile_api_timeout() -> aiohttp.ClientTimeout:    total = float(os.getenv("PROFILE_API_TIMEOUT_TOTAL", "5"))    connect = float(os.getenv("PROFILE_API_CONNECT_TIMEOUT", "3"))    if connect > total:        connect = total    return aiohttp.ClientTimeout(total=total, connect=connect, sock_connect=connect)def _proxy_connection_log_reason(exc: BaseException) -> str:    if isinstance(exc, aiohttp.ClientConnectorError):        os_error = exc.os_error        if os_error is not None and getattr(os_error, "errno", None) == 111:            return "local proxy port refused (xray not listening)"        return f"proxy connect failed: {exc}"    if isinstance(exc, aiohttp.ServerTimeoutError):        return f"timeout waiting for API via proxy: {exc}"    if isinstance(exc, aiohttp.ClientPayloadError):        return f"broken response via proxy: {exc}"    if isinstance(exc, asyncio.TimeoutError):        return "asyncio timeout via proxy"    return f"{type(exc).__name__}: {exc}"def summarize_failure_reason(reason: str) -> str:    """Краткая причина для однострочного лога аккаунта."""    lower = reason.lower()    if "429" in reason:        return "HTTP 429"    if "proxy pool exhausted" in lower:        return "все прокси в cooldown"    if "local proxy port refused" in lower:        return "локальный порт прокси недоступен"    if "timeout" in lower or "asyncio timeout" in lower:        return "таймаут соединения"    if "proxy connect failed" in lower:        return "нет соединения через прокси"    if reason.startswith("API HTTP "):        return reason    if len(reason) > 120:        return reason[:117] + "..."    return reasondef profile_fetch_max_attempts(pool: Optional["ProxyPool"] = None) -> int:    if pool is None:        return 1    configured = int(os.getenv("PROFILE_FETCH_MAX_RETRIES", "10"))    if configured <= 0:        return pool.size    return min(configured, pool.size)def _parse_stats_payload(data: Dict[str, Any]) -> Optional[Dict[str, Any]]:    if not isinstance(data, dict):        return None    if "error" in data:        logger.error("API error in response body: %s", data.get("error"))        return None    if "response" not in data:        logger.warning("No 'response' field in API response")        return None    stats = data.get("response") or {}    if not isinstance(stats, dict) or not stats:        logger.warning("Empty 'response' field in API response")        return None    for field in (        "earnedCrystals",        "kills",        "deaths",        "caughtGolds",        "score",        "scoreNext",    ):        if field in stats and not isinstance(stats[field], (int, float)):            return None    if "name" in stats and not isinstance(stats["name"], str):        return None    for field in (        "modesPlayed",        "turretsPlayed",        "hullsPlayed",        "dronesPlayed",        "resistanceModules",        "suppliesUsage",    ):        if field not in stats:            continue        items = stats[field]        if not isinstance(items, list) or any(            not isinstance(item, dict) for item in items        ):            return None        for item in items:            if field == "modesPlayed" and not isinstance(item.get("type"), str):                return None            for key in ("scoreEarned", "timePlayed", "usages"):                if key in item and not isinstance(item[key], (int, float)):                    return None            if "name" in item and not isinstance(item["name"], str):                return None    if "paintsPlayed" in stats:        del stats["paintsPlayed"]    return statsasync def _fetch_once(    session: aiohttp.ClientSession,    api_url: str,    proxy_url: Optional[str],) -> Dict[str, Any]:    try:        async with session.get(            api_url,            proxy=proxy_url,            timeout=profile_api_timeout(),        ) as response:            if response.status == 429:                raise RateLimitExceeded("HTTP 429 from Tanki API")            if response.status != 200:                raise TankiStatsError(f"API HTTP {response.status}")            return await response.json()    except aiohttp.ClientResponseError as exc:        if exc.status == 429:            raise RateLimitExceeded("HTTP 429 from Tanki API") from exc        raise TankiStatsError(f"API HTTP {exc.status}") from exc    except aiohttp.ClientError as exc:        log_reason = _proxy_connection_log_reason(exc)        raise ProxyConnectionError(            "Failed to reach Tanki API", log_reason=log_reason        ) from exc    except asyncio.TimeoutError as exc:        log_reason = _proxy_connection_log_reason(exc)        raise ProxyConnectionError(            "Failed to reach Tanki API", log_reason=log_reason        ) from exc    except ValueError as exc:        raise ProxyConnectionError(            "Invalid JSON from Tanki API", log_reason="invalid API JSON"        ) from excasync def _rotate_after_rate_limit(    proxy_pool: "ProxyPool",    proxy_url: Optional[str],) -> Optional[str]:    from proxy.pool import TAG_API_429, ProxyPoolExhausted    reason = "HTTP 429 from Tanki API (proxy reached API)"    await proxy_pool.mark_rate_limited(proxy_url, reason=reason)    try:        return await proxy_pool.rotate_for_current_task(            cooldown_previous=False,            rotation_tag=TAG_API_429,            rotation_reason=reason,        )    except ProxyPoolExhausted as exc:        raise RateLimitExceeded("All proxies in cooldown after 429") from excasync def _rotate_after_connection_error(    proxy_pool: "ProxyPool",    proxy_url: Optional[str],    *,    log_reason: str,) -> Optional[str]:    from proxy.pool import TAG_PROXY, ProxyPoolExhausted    await proxy_pool.mark_connection_failed(proxy_url, reason=log_reason)    try:        return await proxy_pool.rotate_for_current_task(            cooldown_previous=False,            rotation_tag=TAG_PROXY,            rotation_reason=log_reason,        )    except ProxyPoolExhausted as exc:        raise ProxyConnectionError(            "All proxies temporarily unavailable",            log_reason="proxy pool exhausted",        ) from excasync def fetch_tanki_stats(    session: aiohttp.ClientSession,    api_url: str,    proxy_pool: Optional["ProxyPool"] = None,) -> Tuple[Optional[Dict[str, Any]], Optional[str]]:    """Fetch profile stats from Tanki API with proxy rotation and cooldowns.    Returns:        (stats, None) on success, or (None, failure_reason) on failure.    """    proxy_url: Optional[str] = None    if proxy_pool is not None:        proxy_url = await proxy_pool.get_for_current_task()    max_attempts = profile_fetch_max_attempts(proxy_pool)    consecutive_429 = 0    abort_429_after = int(os.getenv("PROFILE_FETCH_429_ABORT", "3"))    last_failure: Optional[str] = None    for attempt in range(max_attempts):        try:            payload = await _fetch_once(session, api_url, proxy_url)            if proxy_pool is not None:                await proxy_pool.mark_success(proxy_url)            stats = _parse_stats_payload(payload)            return (                (stats, None)                if stats is not None                else (None, "empty or invalid API response")            )        except RateLimitExceeded:            consecutive_429 += 1            last_failure = "HTTP 429 from Tanki API"            if consecutive_429 >= abort_429_after:                if proxy_pool is not None:                    await proxy_pool.mark_rate_limited(proxy_url, reason=last_failure)                logger.debug(                    "Aborting after %d consecutive 429 responses", consecutive_429                )                return None, f"HTTP 429 ({consecutive_429} подряд)"            if proxy_pool is None or attempt >= max_attempts - 1:                if proxy_pool is not None:                    await proxy_pool.mark_rate_limited(proxy_url, reason=last_failure)                return None, last_failure            try:                proxy_url = await _rotate_after_rate_limit(proxy_pool, proxy_url)            except RateLimitExceeded:                return None, "proxy pool exhausted"            logger.debug("Rotated proxy after 429 -> %s", proxy_url)        except ProxyConnectionError as exc:            consecutive_429 = 0            last_failure = exc.log_reason            logger.debug(                "Connection error on attempt %d/%d: %s",                attempt + 1,                max_attempts,                exc.log_reason,            )            if proxy_pool is None or attempt >= max_attempts - 1:                if proxy_pool is not None:                    await proxy_pool.mark_connection_failed(                        proxy_url, reason=last_failure                    )                return None, last_failure            try:                proxy_url = await _rotate_after_connection_error(                    proxy_pool,                    proxy_url,                    log_reason=exc.log_reason,                )            except ProxyConnectionError as rotation_error:                return None, rotation_error.log_reason            logger.debug("Rotated proxy after connection error -> %s", proxy_url)        except TankiStatsError as exc:            consecutive_429 = 0            last_failure = str(exc)            if last_failure == "API HTTP 404":                return None, last_failure            logger.debug(                "API error on attempt %d/%d: %s", attempt + 1, max_attempts, exc            )            if proxy_pool is None or attempt >= max_attempts - 1:                return None, last_failure            from proxy.pool import TAG_API, ProxyPoolExhausted            try:                proxy_url = await proxy_pool.rotate_for_current_task(                    rotation_tag=TAG_API,                    rotation_reason=str(exc),                )            except ProxyPoolExhausted:                return None, "proxy pool exhausted"    return None, last_failure